using UnityEngine;
[DefaultExecutionOrder(500)] public class LocomotiveDynamicsV10:MonoBehaviour {
 public LocomotiveController engine;public LocomotiveThermalEffects thermal;public LocomotivePresentationV4 presentation;public LocomotiveDriveV9 drive;
 public ParticleSystem fireboxSmoke,boiling,condensation;public ParticleSystem[] brakeDust;public Transform[] shoes;public Renderer waterSurface,beam;public float heat,brakeAmount,acceleration;public int emittedBubbles;public Vector3[] shoeHomes;
 Material waterMat,beamMat;AudioSource rolling,braking,release;float previousVelocity;bool wasBraking;
 void Start(){if(waterSurface)waterMat=waterSurface.material;if(beam)beamMat=beam.material;shoeHomes=new Vector3[shoes.Length];for(int i=0;i<shoes.Length;i++)shoeHomes[i]=shoes[i].localPosition;rolling=Audio("轮轨滚动",MakeSound(false),true);braking=Audio("闸瓦摩擦",MakeSound(true),true);release=Audio("制动排气",presentation.steamClip,false);}
 AudioSource Audio(string name,AudioClip clip,bool loop){var g=new GameObject(name);g.transform.SetParent(engine.locomotive,false);g.transform.localPosition=new Vector3(0,.55f,0);var a=g.AddComponent<AudioSource>();a.clip=clip;a.loop=loop;a.spatialBlend=.5f;a.minDistance=4;a.maxDistance=30;a.volume=0;if(loop)a.Play();return a;}
 AudioClip MakeSound(bool brake){const int sr=22050;var samples=new float[sr*3];var rng=new System.Random(brake?84:43);float low=0;for(int i=0;i<samples.Length;i++){float t=i/(float)sr,noise=(float)rng.NextDouble()*2-1;low=Mathf.Lerp(low,noise,brake?.20f:.04f);float joint=Mathf.Pow(.5f+.5f*Mathf.Cos(t*Mathf.PI*8),18);samples[i]=brake?low*.40f+Mathf.Sin(t*Mathf.PI*2*873)*.055f*(.7f+.3f*Mathf.Sin(t*33)):low*.5f+noise*.045f+joint*low*.5f;}var clip=AudioClip.Create(brake?"BrakeFriction":"RailRolling",samples.Length,1,sr,false);clip.SetData(samples,0);return clip;}
 void EmitRate(ParticleSystem ps,float rate){if(!ps)return;var em=ps.emission;em.enabled=rate>.01f;em.rateOverTime=rate;if(rate>.01f&&!ps.isPlaying)ps.Play();}
 void LateUpdate(){float dt=Mathf.Max(.0001f,Time.deltaTime);bool complete=engine.freeAssembly&&engine.freeAssembly.Complete;bool burning=thermal.fireEnabled&&thermal.HasModule(0)&&!engine.exploded;heat=Mathf.MoveTowards(heat,burning?1:0,dt*(burning?.45f:.22f));float velocity=drive.signedRpm*Mathf.PI*1.3f/60;acceleration=(velocity-previousVelocity)/dt;bool decel=Mathf.Abs(velocity)+.003f<Mathf.Abs(previousVelocity);float target=complete&&engine.travel&&decel?Mathf.Clamp01(Mathf.Abs(acceleration)/3.2f):0;brakeAmount=Mathf.MoveTowards(brakeAmount,target,dt*4);previousVelocity=velocity;
  bool active=complete&&engine.travel&&Mathf.Abs(velocity)>.04f;float speed=Mathf.Abs(velocity);if(rolling){rolling.volume=Mathf.MoveTowards(rolling.volume,presentation.audioOn&&active?Mathf.Clamp01(speed/4)*.30f:0,dt*.8f);rolling.pitch=.65f+speed*.18f;}if(braking){braking.volume=Mathf.MoveTowards(braking.volume,presentation.audioOn?brakeAmount*Mathf.Clamp01(speed)*.35f:0,dt*1.5f);braking.pitch=.75f+speed*.08f;}if(brakeAmount>.45f&&!wasBraking&&presentation.audioOn){release.volume=.18f;release.PlayOneShot(presentation.steamClip,.25f);}wasBraking=brakeAmount>.2f;
  for(int i=0;i<shoes.Length;i++){shoes[i].gameObject.SetActive(complete);shoes[i].localPosition=shoeHomes[i]+Vector3.right*(.018f*(1-brakeAmount));}foreach(var ps in brakeDust)EmitRate(ps,active&&speed>1.1f?brakeAmount*8:0);
  if(thermal.smoke){var em=thermal.smoke.emission;em.rateOverTime=burning&&thermal.HasModule(5)?100+engine.rpm*1.0f:0;var vel=thermal.smoke.velocityOverLifetime;vel.enabled=true;vel.space=ParticleSystemSimulationSpace.World;vel.x=-velocity*.15f;}
  bool section=engine.principle&&burning;EmitRate(fireboxSmoke,section?heat*50:0);EmitRate(boiling,section?heat*110:0);EmitRate(condensation,section?heat*4:0);if(waterMat)waterMat.SetFloat("_Heat",heat);if(beamMat)beamMat.SetFloat("_Intensity",presentation.lightBlend);emittedBubbles=boiling?boiling.particleCount:0;
  if(engine.travel){engine.SetCamera();float amplitude=active?.0015f*Mathf.Clamp01(speed/2)+brakeAmount*.005f:0;engine.studioCamera.transform.position+=engine.studioCamera.transform.up*(Mathf.Sin(Time.time*35)*amplitude)+engine.studioCamera.transform.right*(Mathf.Sin(Time.time*23)*amplitude*.5f);}
 }
 void OnDestroy(){if(waterMat)Destroy(waterMat);if(beamMat)Destroy(beamMat);}
}
